import ast,copy,hashlib,json
from pathlib import Path
root=Path('/workspace');runtime=json.load(open(root/'runtime_view.json'));proposal=json.load(open(root/'proposal.json'))
def validate(value,schema,path='study'):
 typ=schema.get('type')
 ok={'object':lambda:isinstance(value,dict),'array':lambda:isinstance(value,list),'string':lambda:isinstance(value,str),'boolean':lambda:isinstance(value,bool)}
 if typ in ok:assert ok[typ](),path
 if 'const' in schema:assert value==schema['const'],path
 if 'enum' in schema:assert value in schema['enum'],path
 if isinstance(value,dict):
  assert not(set(schema.get('required',[]))-set(value)),path
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False:assert set(value)<=set(props),path
  for k,v in value.items():
   if k in props:validate(v,props[k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,v in enumerate(value):validate(v,schema.get('items',{}),path+'['+str(i)+']')
 if isinstance(value,str):assert len(value)>=schema.get('minLength',0),path
validate(proposal['study'],runtime['study_schema'])
assert proposal['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids']);assert set(proposal['study']['evidence_refs'])<=allowed
assert proposal['parent_trial'] in allowed
for c in proposal['study']['contrasts']:assert c['parent_ref'] in allowed
assert 1<=len(proposal['variants'])<=4
assert any(v['role']=='candidate' for v in proposal['variants'])
assert len({v['name'] for v in proposal['variants']})==len(proposal['variants'])
canonical=[]
old=ast.parse((root/'history_g0_r0017_available_norm.py').read_text())
oldcls=next(n for n in old.body if isinstance(n,ast.ClassDef));oldmethods={n.name:n for n in oldcls.body if isinstance(n,ast.FunctionDef)}
for v in proposal['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 text=(root/v['file']).read_text();t=ast.parse(text)
 assert hashlib.sha256(text.encode()).hexdigest() in v['note']
 cfg=next(n for n in t.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets))
 assert ast.literal_eval(cfg.value)==v['config']
 cls=next(n for n in t.body if isinstance(n,ast.ClassDef));methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 init=methods['__init__'];ds=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,val in v['config'].items():
  d=ast.literal_eval(ds[k]);assert list(d)==val if isinstance(d,tuple) else d==val
 for name in oldmethods:
  if name not in ('__init__','_target_match_summary','_joint_coefficients'):assert ast.dump(methods[name])==ast.dump(oldmethods[name]),name
 # Allocation calls are identical, so the parameter-count estimate is unchanged.
 def allocations(tree):
  return [ast.dump(n) for n in ast.walk(tree) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn']
 assert allocations(t)==allocations(old)
 for n in ast.walk(t):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[n.module] if isinstance(n,ast.ImportFrom) else [a.name for a in n.names]
   assert all(x.split('.')[0] in ('torch','unirank') for x in names)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in ('open','eval','exec','compile','__import__')
 for k,val in zip(cfg.value.keys,cfg.value.values):
  if k.value=='match_balance':val.value='MODE'
 ds['match_balance'].value='MODE';canonical.append(ast.dump(t))
 print(v['file'],'syntax/API/CONFIG/hash/allocations/inherited-method checks passed')
assert len(set(canonical))==1
names={v['name'] for v in proposal['variants']}
for a in proposal['knowledge_assessments']:
 assert a['decision'] in ('used','considered','rejected','unresolved')
 assert set(a['variant_names'])<=names
required_industry={'unirank-method-unimixer','unirank-method-tokenmixer','unirank-method-rankmixer'}
assert required_industry<={a['knowledge_id'] for a in proposal['knowledge_assessments']}
print('Study schema, protocol, evidence IDs, contrasts, all industry assessments and cross-cell source parity passed.')
(root/'runtime_view.json').unlink()
print('Removed temporary runtime view; final outputs: proposal.json and three model modules.')
PY"

